package printer

import (
	"testing"
)

// TestSendToPythonSimulator connects to the Python virtual printer simulator on port 9100
// and verifies transmission of ESC/POS commands generated by the Go bridge.
func TestSendToPythonSimulator(t *testing.T) {
	p, err := NewTCPPrinter("127.0.0.1", 9100)
	if err != nil {
		t.Fatalf("Printer connection failed: %v", err)
	}
	defer p.Close()

	// ESC/POS test commands generated by Go
	data := []byte{
		0x1B, 0x40,       // Initialize printer (ESC @)
		0x1B, 0x61, 0x01, // Center alignment (ESC a 1)
	}
	data = append(data, []byte("URQR GO BRIDGE TEST\n")...)
	data = append(data, []byte("Sent from Go to Python simulator\n")...)
	data = append(data,
		0x1B, 0x61, 0x00, // Left alignment
		0x0A, 0x0A,       // Line feeds
		0x1D, 0x56, 0x00, // Paper cut
	)

	elapsed, err := p.Send(data)
	if err != nil {
		t.Fatalf("Failed to send printer data: %v", err)
	}

	t.Logf("Successfully sent %d bytes to %s in %s", len(data), p.Addr(), elapsed)
}
